<!-- 文件作用：在小程序内管理用户、服务、俱乐部、订单争议、游戏主题、公告和操作审计。 -->
<template><AppShell title="平台管理" subtitle="把每一次信任，落实在细节里" back><view v-if="error" class="error-box mb">{{ error }}</view><EmptyState v-if="state.ready && state.user?.role!=='admin'" title="仅平台管理员可访问" detail="权限由服务端核验，请使用管理员账号登录" icon="shield"><button class="btn" @click="go('/pages/login/index')">切换账号</button></EmptyState><template v-else-if="state.user?.role==='admin'">
<view class="overview"><view v-for="metric in metrics" :key="metric.key" class="metric"><text class="metric-value">{{ metric.money?'¥'+money(overview[metric.key]):overview[metric.key]||0 }}</text><text class="metric-name">{{ metric.label }}</text></view></view><view class="admin-alert" v-if="overview.pending_services||overview.pending_clubs||overview.disputed_orders"><Icon name="bell" :size="18"/><text>{{ overview.pending_services||0 }} 个服务待审核 · {{ overview.pending_clubs||0 }} 个俱乐部申请 · {{ overview.disputed_orders||0 }} 个争议</text></view><scroll-view scroll-x class="admin-tabs"><view class="tabs"><button v-for="item in tabs" :key="item.id" :class="['tab',{active:tab===item.id}]" @click="selectTab(item.id)">{{ item.name }}</button></view></scroll-view>
<view class="admin-toolbar" v-if="tab!=='settings'"><input v-model="query" class="input" placeholder="搜索全部名称、用户或订单号" confirm-type="search" @confirm="loadData()"/><button class="btn-secondary refresh-btn" :disabled="loading" @click="loadData()"><Icon name="refresh" :size="18"/></button></view><view v-if="loading" class="loading-line">正在加载管理数据…</view>
<template v-else-if="tab==='users'"><view v-for="user in filtered" :key="user.id" class="admin-card panel"><view class="row between"><view class="row"><view class="avatar">{{ user.nickname?.slice(0,1) }}</view><view class="stack compact"><text class="item-title">{{ user.nickname }}</text><text class="hint">{{ user.role==='admin'?'平台管理员':user.provider_enabled?'玩家 / 打手':'玩家' }} · {{ user.id }}</text></view></view><text :class="user.status==='frozen'?'danger':'accent'" class="small">{{ user.status==='frozen'?'已冻结':'正常' }}</text></view><text class="muted">{{ user.bio||'暂未填写简介' }}</text><button v-if="user.id!==state.user.id" :class="['btn btn-small',user.status==='frozen'?'btn-secondary':'btn-danger']" :disabled="busy" @click="updateItem('users',user.id,{status:user.status==='frozen'?'active':'frozen'})">{{ user.status==='frozen'?'解除冻结':'冻结账户' }}</button></view></template>
<template v-else-if="tab==='services'"><view v-for="service in filtered" :key="service.id" class="admin-card panel"><view class="row between"><text class="item-title">{{ service.title }}</text><text class="pill">{{ statusLabel(service.status) }}</text></view><view class="service-summary"><image :src="assetUrl(service.cover_url)" mode="aspectFill"/><view class="stack compact"><text>{{ service.provider_name }} · {{ service.category }}</text><text class="accent">¥{{ money(service.price_cents) }}/{{ service.unit }}</text><text class="hint">{{ service.description }}</text></view></view><view class="admin-actions"><button v-if="service.status!=='active'" class="btn btn-small" :disabled="busy" @click="updateItem('services',service.id,{status:'active'})">审核通过</button><button v-if="service.status==='pending'" class="btn btn-secondary btn-small" :disabled="busy" @click="updateItem('services',service.id,{status:'rejected'})">不予通过</button><button v-if="service.status==='active'" class="btn btn-secondary btn-small" :disabled="busy" @click="updateItem('services',service.id,{status:'paused'})">下架服务</button><button class="text-btn" @click="go('/pages/service/index?id='+service.id)">查看详情</button></view></view></template>
<template v-else-if="tab==='clubs'"><view v-for="club in filtered" :key="club.id" class="admin-card panel"><view class="row between"><text class="item-title">{{ club.name }}</text><text class="pill">{{ club.verified?'已认证':statusLabel(club.status) }}</text></view><text class="muted">负责人 {{ club.owner_name }} · {{ club.member_count||0 }} 位成员</text><text class="small">{{ club.description }}</text><view class="admin-actions"><button v-if="club.status!=='active'" class="btn btn-small" :disabled="busy" @click="updateItem('clubs',club.id,{status:'active',verified:true})">通过并认证</button><button v-if="club.status==='pending'" class="btn btn-secondary btn-small" :disabled="busy" @click="updateItem('clubs',club.id,{status:'rejected',verified:false})">拒绝申请</button><button v-if="club.status==='active'" class="btn btn-secondary btn-small" :disabled="busy" @click="updateItem('clubs',club.id,{status:'active',verified:!club.verified})">{{ club.verified?'取消认证':'授予认证' }}</button><button class="text-btn" @click="go('/pages/club/index?id='+club.id)">成员 / 订单</button></view></view></template>
<template v-else-if="tab==='orders'"><view class="tabs mb"><button :class="['tab',{active:!disputesOnly}]" @click="disputesOnly=false;loadData()">全部订单</button><button :class="['tab',{active:disputesOnly}]" @click="disputesOnly=true;loadData()">退款与争议</button></view><view v-for="order in displayedOrders" :key="order.id" class="admin-card panel" @click="go('/pages/order/index?id='+order.id)"><view class="row between"><text class="item-title">{{ order.title }}</text><text class="accent nowrap">¥{{ money(order.amount_cents) }}</text></view><text class="hint">{{ order.order_no }}</text><text class="small">{{ order.buyer_name }} → {{ order.provider_name||'未接单' }}</text><view class="row between"><text class="pill">{{ statusLabel(order.status) }}</text><text v-if="order.refund_status && order.refund_status!=='none'" class="refund-tag">{{ refundName(order.refund_status) }}</text></view><text class="text-btn">查看证据与处理争议</text></view></template>
<template v-else-if="tab==='games'"><view class="row between mb"><text class="hint">颜色、封面、分类会同步到客户端</text><button class="text-btn" @click="editGame()">＋ 新增游戏</button></view><view v-for="game in filtered" :key="game.id" class="admin-card panel"><view class="game-admin-heading"><image :src="assetUrl(game.cover_url)" mode="aspectFill"/><view><text class="item-title">{{ game.name }}</text><view class="game-colors"><text v-for="key in colorKeys" :key="key.id" :style="{background:game[key.id]}"/></view><text class="hint">{{ (game.categories||[]).join(' / ') }}</text></view></view><view class="row between"><text class="pill">{{ game.enabled?'已启用':'已隐藏' }}</text><button class="btn btn-secondary btn-small" @click="editGame(game)">编辑主题与封面</button></view></view></template>
<template v-else-if="tab==='audit'"><view v-for="(entry,index) in filtered" :key="entry.id||index" class="audit-entry"><view class="row between"><text class="item-title">{{ entry.action||entry.operation }}</text><text class="hint">{{ time(entry.created_at) }}</text></view><text class="muted">{{ entry.actor_name||entry.user_id||entry.actor_id }} · {{ entry.target_id||entry.entity_id }}</text><text v-if="entry.note||entry.detail||entry.details" class="hint audit-detail">{{ stringify(entry.note||entry.detail||entry.details) }}</text></view></template>
<view v-else-if="tab==='settings'" class="panel"><view class="field"><text class="field-label">平台名称</text><input v-model="settings.site_name" class="input" maxlength="20"/></view><view class="field"><text class="field-label">首页公告</text><textarea v-model="settings.announcement" class="input" maxlength="300"/></view><button class="btn" :disabled="busy" @click="saveSettings">保存平台设置</button><text class="hint block">登录密钥与支付证书由服务器环境配置，不在客户端存储。</text></view>
<button v-if="hasMore && !loading" class="btn-secondary load-more" @click="loadData(true)">加载更多记录</button><EmptyState v-if="!loading && tab!=='settings' && !filtered.length" title="没有匹配的数据" detail="可以更换关键词或稍后刷新" icon="search"/>
</template>
<view v-if="editing" class="modal-mask" @click="editing=false"><scroll-view scroll-y class="game-modal panel" @click.stop><view class="row between mb"><text class="section-title">{{ newGame?'添加游戏':'编辑游戏主题' }}</text><button class="text-btn" @click="editing=false">关闭</button></view><view class="field" v-if="newGame"><text class="field-label">游戏标识（小写英文）</text><input v-model="gameForm.id" class="input" placeholder="例如 league" maxlength="30"/></view><view class="two-fields"><view class="field"><text class="field-label">游戏名称</text><input v-model="gameForm.name" class="input" maxlength="30"/></view><view class="field"><text class="field-label">简称</text><input v-model="gameForm.short_name" class="input" maxlength="8"/></view></view><view class="field"><text class="field-label">主题标语</text><input v-model="gameForm.subtitle" class="input" maxlength="80"/></view><view class="two-fields"><view class="field" v-for="key in colorKeys" :key="key.id"><text class="field-label">{{ key.name }}</text><view class="color-input"><text :style="{background:gameForm[key.id]}"/><input v-model="gameForm[key.id]" maxlength="7" placeholder="#00e18a"/></view></view></view><view class="field"><text class="field-label">服务分类（逗号分隔）</text><input v-model="gameForm.categoriesText" class="input" placeholder="陪练教学,组队陪玩,任务协作"/></view><view class="row between mb"><text class="field-label">封面素材库</text><button class="text-btn" :disabled="busy" @click="uploadCover">上传封面</button></view><view class="cover-library"><view v-for="cover in coverLibrary" :key="cover" :class="['library-cover',{selected:gameForm.covers.includes(cover)}]" @click="toggleCover(cover)"><image :src="assetUrl(cover)" mode="aspectFill"/><view v-if="gameForm.covers.includes(cover)" class="library-number">{{ gameForm.covers.indexOf(cover)+1 }}</view></view></view><text class="hint block">按选择顺序排列，第一张作为游戏主封面，至少选择一张。</text><view class="two-fields"><view class="field"><text class="field-label">排序（越小越靠前）</text><input v-model="gameForm.sort_order" type="number" class="input"/></view><view class="field"><text class="field-label">游戏状态</text><switch :checked="gameForm.enabled" color="#00e18a" @change="gameForm.enabled=$event.detail.value"/><text class="hint">{{ gameForm.enabled?'对玩家可见':'暂时隐藏' }}</text></view></view><button class="btn" :disabled="busy" @click="saveGame">{{ busy?'保存中…':'保存游戏配置' }}</button><view class="modal-bottom"/></scroll-view></view>
</AppShell></template>
<script setup>
/** 文件作用：仅管理员可调用的管理操作，错误可恢复且刷新客户端主题配置。 */
import { ref,reactive,computed } from 'vue'
import { onShow } from '@dcloudio/uni-app'
import AppShell from '../../components/AppShell.vue'
import EmptyState from '../../components/EmptyState.vue'
import Icon from '../../components/Icon.vue'
import { state,init } from '../../lib/store'
import { api,API_BASE,token } from '../../lib/api'
import { go,notify,money,time,statusLabel,assetUrl } from '../../lib/format'
const hasMore=ref(false)
let loadVersion=0
const overview=ref({}),data=ref([]),tab=ref('services'),query=ref(''),loading=ref(false),busy=ref(false),error=ref(''),disputesOnly=ref(false),editing=ref(false),newGame=ref(false),settings=reactive({site_name:'',announcement:''}),gameForm=reactive({}),uploadedCovers=ref([])
const tabs=[{id:'services',name:'服务审核'},{id:'clubs',name:'俱乐部'},{id:'orders',name:'订单与售后'},{id:'users',name:'用户'},{id:'games',name:'游戏配置'},{id:'audit',name:'操作记录'},{id:'settings',name:'平台设置'}]
const metrics=[{key:'users',label:'注册用户'},{key:'orders',label:'全部订单'},{key:'services',label:'服务数量'},{key:'revenue_cents',label:'完成交易额',money:true}]
const colorKeys=[{id:'primary_color',name:'主题强调色'},{id:'bg_color',name:'页面背景色'},{id:'surface_color',name:'卡片背景色'},{id:'text_color',name:'正文颜色'}]
const filtered=computed(()=>data.value)
const displayedOrders=computed(()=>filtered.value.filter(order=>!disputesOnly.value||(order.refund_status&&order.refund_status!=='none')||order.status==='disputed'))
const coverLibrary=computed(()=>[...new Set([...state.games.flatMap(game=>game.covers||[]),...(gameForm.covers||[]),...uploadedCovers.value])])
/** 加载管理员摘要与当前数据，直接访问时也验证身份。 */
async function load(){try{await init(true);if(state.user?.role!=='admin')return;overview.value=await api('/admin/overview');await loadData()}catch(e){error.value=e.message}}
/** 请求当前分类的管理数据，避免将前一分类的记录短暂展示。 */
async function loadData(append=false){
  const version=++loadVersion,currentTab=tab.value
  loading.value=true;error.value=''
  try{
    const path='/admin/'+currentTab+'?limit=100&offset='+(append?data.value.length:0)+'&q='+encodeURIComponent(query.value.trim())+(currentTab==='orders'&&disputesOnly.value?'&refund=1':'')
    const result=await api(path)
    if(version!==loadVersion)return
    if(currentTab==='settings'){Object.assign(settings,result);hasMore.value=false}
    else{const items=Array.isArray(result)?result:[];data.value=append?[...data.value,...items]:items;hasMore.value=items.length===100}
  }catch(e){if(version===loadVersion)error.value=e.message}finally{if(version===loadVersion)loading.value=false}
}
/** 切换分类后清空搜索与旧记录。 */
function selectTab(value){tab.value=value;query.value='';data.value=[];loadData()}
/** 提交审核或账户状态变更，服务端保留审计记录。 */
async function updateItem(type,id,body){if(busy.value)return;busy.value=true;try{await api('/admin/'+type+'/'+id,'PATCH',body);await loadData();overview.value=await api('/admin/overview');notify('处理结果已保存')}catch(e){notify(e)}finally{busy.value=false}}
/** 展示退款流程中的准确状态。 */
function refundName(value){return{requested:'等待卖方处理',rejected:'卖方已拒绝',escalated:'申请平台介入',approved:'退款完成',processing:'退款通道处理中'}[value]||value}
/** 格式化审计详情为可读文本。 */
function stringify(value){return typeof value==='string'?value:JSON.stringify(value)}
/** 准备游戏编辑快照，取消编辑不改变已有页面主题。 */
function editGame(game){newGame.value=!game;Object.keys(gameForm).forEach(key=>delete gameForm[key]);Object.assign(gameForm,game?JSON.parse(JSON.stringify(game)):{id:'',name:'',short_name:'',subtitle:'找到合拍的队友',primary_color:'#00e18a',bg_color:'#0a1110',surface_color:'#15201e',text_color:'#f2f5f3',covers:[],enabled:true,sort_order:state.games.length+1});gameForm.categoriesText=(gameForm.categories||['陪练教学','组队陪玩','任务协作']).join(',');editing.value=true}
/** 选择封面和主视觉顺序。 */
function toggleCover(url){const index=gameForm.covers.indexOf(url);if(index>=0)gameForm.covers.splice(index,1);else gameForm.covers.push(url)}
/** 上传公开的游戏素材，与仅订单相关人员可见的证据图片分离。 */
function uploadCover(){uni.chooseImage({count:1,sizeType:['compressed'],success:result=>{busy.value=true;uni.uploadFile({url:API_BASE+'/admin/covers',filePath:result.tempFilePaths[0],name:'file',header:{Authorization:'Bearer '+token()},success:response=>{try{const body=JSON.parse(response.data);if(response.statusCode<200||response.statusCode>=300)throw new Error(body.error||'上传失败');const source=body.data.url;const url=source;uploadedCovers.value.push(url);gameForm.covers.push(url);notify('封面已上传')}catch(e){notify(e)}},fail:()=>notify('图片上传失败'),complete:()=>{busy.value=false}})}})}
/** 校验游戏主题配置，保存后立即刷新公共主题数据。 */
async function saveGame(){if(busy.value)return;if(!/^[a-z][a-z0-9-]{1,29}$/.test(gameForm.id)||!gameForm.name?.trim()||!gameForm.short_name?.trim())return notify('请填写有效游戏标识、名称和简称');if(colorKeys.some(key=>!/^#[0-9a-f]{6}$/i.test(gameForm[key.id])))return notify('颜色请使用六位十六进制值');if(!gameForm.covers.length)return notify('至少选择一张游戏封面');const categories=gameForm.categoriesText.split(/[,，]/).map(item=>item.trim()).filter(Boolean);if(!categories.length)return notify('至少填写一种服务分类');busy.value=true;try{const{categoriesText,...body}=gameForm;await api('/admin/games'+(newGame.value?'':'/'+gameForm.id),newGame.value?'POST':'PATCH',{...body,sort_order:Number(gameForm.sort_order)||0,categories,cover_url:gameForm.covers[0]});editing.value=false;await init(true);await loadData();notify('游戏主题已更新')}catch(e){notify(e)}finally{busy.value=false}}
/** 更新首页公告和平台名称。 */
async function saveSettings(){if(busy.value)return;if(!settings.site_name.trim())return notify('请填写平台名称');busy.value=true;try{await api('/admin/settings','PATCH',settings);await init(true);notify('平台设置已保存')}catch(e){notify(e)}finally{busy.value=false}}
onShow(load)
</script>
<style scoped>
.load-more{margin:20px auto;width:100%}.overview{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin:12px 0 18px}.metric{padding:16px;border:1px solid #ffffff0d;border-radius:13px;background:var(--surface)}.metric-value{display:block;font-size:27px;font-weight:800;letter-spacing:-.8px}.metric-name{display:block;font-size:11px;color:#859c8e;margin-top:5px}.admin-alert{display:flex;align-items:center;gap:10px;color:#c6b989;font-size:10px;background:#be9c2910;padding:12px;border-radius:10px;margin-bottom:20px}.admin-tabs{width:100%;margin:0 0 17px;white-space:nowrap}.admin-toolbar{display:flex;gap:9px;margin-bottom:17px}.admin-toolbar input{font-size:12px}.refresh-btn{padding:0 14px}.admin-card{margin-bottom:13px;display:flex;flex-direction:column;gap:12px}.item-title{font-size:14px;font-weight:650;white-space:normal}.compact{gap:3px}.admin-actions{display:flex;align-items:center;flex-wrap:wrap;gap:9px}.service-summary{display:flex;gap:12px;font-size:12px}.service-summary image{width:75px;height:64px;border-radius:7px;flex-shrink:0}.service-summary .hint{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.refund-tag{font-size:10px;color:#f0bc7a}.game-admin-heading{display:flex;gap:13px}.game-admin-heading image{width:85px;height:70px;border-radius:9px;flex-shrink:0}.game-colors{display:flex;gap:5px;margin:8px 0}.game-colors text{height:12px;width:25px;border-radius:3px;border:1px solid #ffffff22}.audit-entry{padding:18px 0;border-bottom:1px solid #ffffff0d;display:flex;flex-direction:column;gap:7px}.audit-detail{word-break:break-all}.block{display:block;margin-top:12px;margin-bottom:17px}.modal-mask{position:fixed;inset:0;background:#000b;z-index:110;display:flex;align-items:center;justify-content:center;padding:20px}.game-modal{width:100%;max-width:480px;height:85vh;padding:20px}.two-fields{display:grid;grid-template-columns:1fr 1fr;gap:14px}.color-input{display:flex;align-items:center;background:#ffffff06;padding:10px;border:1px solid #ffffff16;border-radius:9px;gap:8px}.color-input>text{width:22px;height:22px;flex-shrink:0;border-radius:5px;border:1px solid #ffffff25}.color-input input{width:100%;font-size:11px}.cover-library{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.library-cover{height:61px;border:2px solid transparent;border-radius:7px;overflow:hidden;position:relative}.library-cover.selected{border-color:var(--accent)}.library-cover image{width:100%;height:100%}.library-number{position:absolute;right:3px;bottom:3px;font-size:9px;color:#06140d;background:var(--accent);width:15px;height:15px;border-radius:50%;text-align:center;line-height:15px}.modal-bottom{height:15px}
</style>
